function nc_exists(PDO $db,string $table):bool{$q=$db->prepare('SELECT COUNT(*) FROM information_schema.tables WHERE table_schema=DATABASE() AND table_name=?');$q->execute([$table]);return (int)$q->fetchColumn()>0;}
function nc_guard(PDO $db):string{$hash=hash_init('sha256');foreach($db->query('SELECT doc_key,kind,payload,revision FROM noa_documents ORDER BY doc_key') as $row)hash_update($hash,nc_json($row));if(nc_exists($db,'noa_user_playlists'))foreach($db->query('SELECT * FROM noa_user_playlists ORDER BY owner_id,playlist_id') as $row)hash_update($hash,nc_json($row));foreach(['noa_songs','noa_acts','noa_originals','studio_pages'] as $table)if(nc_exists($db,$table))foreach($db->query('SELECT * FROM '.$table.' ORDER BY 1') as $row)hash_update($hash,nc_json($row));if(nc_exists($db,'noa_source_files'))foreach($db->query('SELECT path_hash,sha256 FROM noa_source_files ORDER BY path_hash') as $row)hash_update($hash,nc_json($row));return hash_final($hash);}
