 $availability=require __DIR__.'/media-status.php';
 foreach($db->query("SELECT doc_key,kind,payload,revision FROM noa_documents WHERE kind IN ('single','playlist','story') ORDER BY doc_key") as $row){$d=json_decode($row['payload'],true,512,JSON_THROW_ON_ERROR);$path='곡/'.($d['sourcePath']??'');if($path==='곡/')$path='document/'.$row['doc_key'];$hash=hash('sha256',$row['payload']);$pool[$hash]??=base64_encode($row['payload']);$video=nc_text($d['body']['youtubeUrl']??'');preg_match('~(?:youtu[.]be/|[?&]v=|/shorts/)([A-Za-z0-9_-]{11})~',$video,$m);$public=!empty($m[1])&&(($availability['videos'][$m[1]]['status']??'')==='public'||(($d['mediaAvailability']['youtubeId']??'')===$m[1]&&($d['mediaAvailability']['status']??'')==='public'));$sources[]=['namespace'=>'mysql:noa_documents','path'=>$path,'legacyKey'=>$row['doc_key'],'sha256'=>$hash,'raw'=>$pool[$hash],'kind'=>$row['kind'],'publicVerified'=>$public];}
