 if(nc_exists($db,'noa_user_playlists'))foreach($db->query('SELECT owner_id,playlist_id,title,tracks,revision FROM noa_user_playlists ORDER BY owner_id,playlist_id') as $row){$d=['genreId'=>'user-library','id'=>'user:'.$row['owner_id'].':'.$row['playlist_id'],'ownerId'=>$row['owner_id'],'title'=>$row['title'],'pkg'=>['songs'=>array_map(fn($key)=>['legacyKey'=>$key],json_decode($row['tracks'],true,512,JSON_THROW_ON_ERROR))]];$raw=nc_json($d);$sources[]=['namespace'=>'mysql:noa_user_playlists','path'=>$row['owner_id'].'/'.$row['playlist_id'],'sha256'=>hash('sha256',$raw),'raw'=>base64_encode($raw),'kind'=>'playlist'];}
 // Older SQL tables are read only if the expected source columns exist.
