}
function nc_plan_path(string $id):string{return lab_root().'/catalog-'.lab_id(substr($id,0,32)).'.json.gz';}
function nc_prepare(PDO $db):array{
 $guard=nc_guard($db);[$sources,$limits]=nc_collect($db);$plan=nc_merge($sources,$limits);if($guard!==nc_guard($db))throw new DomainException('source_changed_during_analysis');$plan['sourceGuard']=$guard;$plan['blobs']=[];foreach($plan['sources'] as &$s){$plan['blobs'][$s['sha256']]??=$s['raw'];unset($s['raw']);}unset($s);foreach($plan['entities'] as &$e)unset($e['candidates']);unset($e);$path=nc_plan_path($plan['digest']);$raw=gzencode(nc_json($plan),6);$temp=tempnam(lab_root(),'.catalog-');chmod($temp,0600);file_put_contents($temp,$raw);rename($temp,$path);return $plan;
}
function nc_load_plan(string $id):array{if(!preg_match('/^[a-f0-9]{64}$/D',$id))throw new InvalidArgumentException('invalid_batch');$p=json_decode(gzdecode((string)file_get_contents(nc_plan_path($id))),true,512,JSON_THROW_ON_ERROR);if($p['digest']!==$id)throw new RuntimeException('plan_identity_mismatch');return $p;}
function nc_schema(PDO $db):void{
 $definitions=require __DIR__.'/catalog-schema.php';foreach($definitions as $table=>$sql){if(!str_starts_with($table,'noa_catalog_'))throw new RuntimeException('schema_scope');$db->exec($sql);}
 $expected=['noa_catalog_batches'=>['batch_id','status','report','source_guard','created_by','created_at','applied_at'],'noa_catalog_sources'=>['source_id','namespace','source_path','sha256','raw_bytes','created_at'],'noa_catalog_songs'=>['song_id','identity_json','genre_id','language','version_name','ep'],'noa_catalog_acts'=>['act_id','identity_json','genre_id','act_number'],'noa_catalog_playlists'=>['playlist_id','identity_json','act_id','owner_id'],'noa_catalog_versions'=>['batch_id','entity_id','entity_type','fields_json','fields_sha','review_fields','public_verified'],'noa_catalog_tracks'=>['batch_id','playlist_id','variant_id','position','song_id','raw_json','status'],'noa_catalog_conflicts'=>['batch_id','conflict_id','entity_id','field_name','alternatives','status','resolution','resolved_by','resolved_at'],'noa_catalog_aliases'=>['batch_id','alias_key','entity_id'],'noa_catalog_batch_sources'=>['batch_id','source_id']];foreach($expected as $table=>$columns){$actual=$db->query('SHOW COLUMNS FROM '.$table)->fetchAll(PDO::FETCH_COLUMN);if(array_diff($columns,$actual))throw new RuntimeException('catalog_schema_conflict');}
}
function nc_insert(PDO $db,string $table,array $row,array $keys):void{
 if(!str_starts_with($table,'noa_catalog_'))throw new RuntimeException('write_scope');$columns=array_keys($row);$q=$db->prepare('INSERT IGNORE INTO '.$table.' ('.implode(',',$columns).') VALUES ('.implode(',',array_fill(0,count($row),'?')).')');$q->execute(array_values($row));if($q->rowCount()===0){$where=[];$values=[];foreach($keys as $key){$where[]=$key.'=?';$values[]=$row[$key];}$q=$db->prepare('SELECT '.implode(',',$columns).' FROM '.$table.' WHERE '.implode(' AND ',$where));$q->execute($values);$saved=$q->fetch(PDO::FETCH_ASSOC);foreach($row as $key=>$value)if(!array_key_exists($key,$saved?:[])||($saved[$key]===null?null:(string)$saved[$key])!==($value===null?null:(string)$value))throw new RuntimeException('existing_catalog_record_differs');}
}
// Every application writer shares this lock; a recovery published between chunks
// is checked again before an older import may become the latest edition.
function nc_publication(PDO $db,callable $work):array{
 $q=$db->query("SELECT GET_LOCK('noa_catalog_publication',10)");
 if((int)$q->fetchColumn()!==1)throw new DomainException('catalog_publication_busy_retry');
 try{return $work();}finally{$db->query("SELECT RELEASE_LOCK('noa_catalog_publication')");}
}
function nc_assert_retains_published(PDO $db,array $p):void{
 $latest=$db->query("SELECT batch_id FROM noa_catalog_batches WHERE status='applied' ORDER BY applied_at DESC,batch_id DESC LIMIT 1")->fetchColumn();
 if(!$latest)return;
 $ids=[];foreach($p['entities'] as $e)$ids[$e['id']]=true;
 $q=$db->prepare('SELECT entity_id FROM noa_catalog_versions WHERE batch_id=?');$q->execute([$latest]);
 foreach($q as $row)if(!isset($ids[$row['entity_id']]))throw new DomainException('published_catalog_would_lose_records');
}
function nc_apply(PDO $db,array $p,string $stage,int $offset,string $actor):array{
 return nc_publication($db,fn()=>nc_apply_locked($db,$p,$stage,$offset,$actor));
}
function nc_apply_locked(PDO $db,array $p,string $stage,int $offset,string $actor):array{
 $id=$p['digest'];$size=100;
 if($stage==='start'){
